using System.Collections.Generic;
using LittleLeo;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "RepairWithActionAction", menuName = "Data/Battle/Battle Actions/Hevelius/RepairWithAction Action")]
public class RepairWithActionAction : RepairAction
{
	[Header("RepairWithEffect Action")]
	[SerializeField]
	private BattleAction battleAction;

	[SerializeField]
	private OmenLogic actionLogic;

	[Header("Description")]
	[SerializeField]
	private bool useDirectDescription;

	[SerializeField]
	private bool allSentinels;

	[SerializeField]
	private bool restorePreviousEffects;

	public BattleAction BattleAction => battleAction;

	public bool UseDirectDescription => useDirectDescription;

	public bool AllSentinels => allSentinels;

	public bool RestorePreviousEffects => restorePreviousEffects;

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		if (restorePreviousEffects)
		{
			GetAliveCompanion(target).GetComponent<CompanionEffects>().SetNextTimeRepairedRestorePreviousEffects(value: true);
		}
		CastTarget(target, source);
		actionLogic.ActivateOmen(battleAction, amount, null, source);
	}

	public override void AreaCastTargetAmount(List<GameObject> targets, int amount, GameObject source)
	{
		AreaCastTarget(targets, source);
		InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 4, delegate
		{
			actionLogic.ActivateOmen(battleAction, targets.Count * amount, null, source);
		});
	}
}
